/**
 * Help Chatbot Knowledge Base
 *
 * Content sourced from: UserManual_GRC - EN (Baarez Technology Solutions)
 *
 * Response format:
 *   - answer   → Overview (1–2 line summary)
 *   - steps[]  → Numbered step-by-step instructions
 *   - notes[]  → Validations, dependencies, permissions, warnings
 *   - relatedLinks[] → Navigation links to related pages
 */

export type HelpModule =
  | "general"
  | "organization"
  | "compliance"
  | "risk-management"
  | "asset-management"
  | "internal-audit"
  | "tprm"
  | "grc-admin";

export type ProductScope = "grc" | "tprm" | "audit" | "both";

export interface HelpArticle {
  id: string;
  module: HelpModule;
  category: string;
  question: string;
  alternateQuestions: string[];
  keywords: string[];
  answer: string;
  steps?: string[];
  notes?: string[];
  relatedLinks?: { label: string; href: string }[];
  roles?: string[];
  productScope: ProductScope;
}

export interface HelpModuleInfo {
  id: HelpModule;
  name: string;
  icon: string;
  description: string;
  productScope: ProductScope;
}

